#### Step 3: Add Custom Business Metrics

**.NET - Counter (Claims Processed)**:
```csharp
using Prometheus;

public class ClaimsService
{
    // Define counter with labels
    private static readonly Counter ClaimsProcessed = Metrics.CreateCounter(
        "claims_processed_total",
        "Total number of claims processed",
        new CounterConfiguration
        {
            LabelNames = new[] { "state", "claim_type", "status" }
        });

    public async Task ProcessClaimAsync(Claim claim)
    {
        try
        {
            // Process claim logic...
            await _repository.SaveAsync(claim);

            // Increment counter with labels
            ClaimsProcessed
                .WithLabels(claim.StateCode, claim.ClaimType, "success")
                .Inc();
        }
        catch (Exception ex)
        {
            ClaimsProcessed
                .WithLabels(claim.StateCode, claim.ClaimType, "failed")
                .Inc();
            throw;
        }
    }
}
```

**.NET - Histogram (Payment Amount Distribution)**:
```csharp
using Prometheus;

public class PaymentService
{
    private static readonly Histogram PaymentAmount = Metrics.CreateHistogram(
        "payment_amount_dollars",
        "Distribution of payment amounts in dollars",
        new HistogramConfiguration
        {
            LabelNames = new[] { "state", "payment_type" },
            Buckets = new[] { 100, 500, 1000, 5000, 10000, 50000 }
        });

    public async Task ProcessPaymentAsync(Payment payment)
    {
        // Process payment...

        // Record payment amount
        PaymentAmount
            .WithLabels(payment.StateCode, payment.PaymentType)
            .Observe(payment.Amount);
    }
}
```

**.NET - Gauge (Queue Depth)**:
```csharp
using Prometheus;

public class ClaimsQueueMonitor : BackgroundService
{
    private static readonly Gauge QueueDepth = Metrics.CreateGauge(
        "claims_queue_depth",
        "Current number of claims in processing queue",
        new GaugeConfiguration
        {
            LabelNames = new[] { "queue_name" }
        });

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            // Query queue depth from Azure Service Bus
            var depth = await _serviceBusClient.GetQueueDepthAsync("claims-queue");

            QueueDepth
                .WithLabels("claims-queue")
                .Set(depth);

            await Task.Delay(TimeSpan.FromSeconds(15), stoppingToken);
        }
    }
}
```

**Java (Spring Boot) - Custom Metrics**:
```java
import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import org.springframework.stereotype.Service;

@Service
public class ClaimsService {

    private final Counter claimsProcessed;

    public ClaimsService(MeterRegistry registry) {
        this.claimsProcessed = Counter.builder("claims_processed_total")
            .description("Total claims processed")
            .tag("application", "claims-service")
            .register(registry);
    }

    public void processClaim(Claim claim) {
        // Process claim...

        // Increment counter
        claimsProcessed.increment();
    }
}
```

**Node.js - Custom Metrics**:
```javascript
const promClient = require('prom-client');

// Define counter
const claimsProcessed = new promClient.Counter({
  name: 'claims_processed_total',
  help: 'Total claims processed',
  labelNames: ['state', 'claim_type', 'status']
});

// Increment counter
async function processClaim(claim) {
  try {
    // Process claim logic...
    await repository.save(claim);

    claimsProcessed.labels(claim.state, claim.claimType, 'success').inc();
  } catch (error) {
    claimsProcessed.labels(claim.state, claim.claimType, 'failed').inc();
    throw error;
  }
}
```

